use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigInnerLabelAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantConfigInnerLabelAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getInnerLabel returns null on a freshly created holder.
     */
    public function testInnerLabelNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigInnerLabelAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isInnerLabelAssigned());
        $this->assertNull($holder->getInnerLabel());
    }
}
class ImplWithTenantConfigInnerLabelAttributeHolderUnitTest
{
    use TenantConfigInnerLabelAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedInnerLabelRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultInnerLabel();
    }
}
